import React from 'react';
import FilmCard from './FilmCard';

// Оновлені дані, які відповідають структурі FilmCard
const sampleFilms = [
    { 
        id: 1, 
        name: 'Taylor Swift: The Eras Tour', 
        time: 169, 
        IMDb_rating: 8.0, 
        price: 300,
        // Переконайтеся, що назва файлу тут ТОЧНО збігається з файлом у папці public/films_photo
        // Якщо у вас файли називаються film1.jpg, film2.jpg - змініть тут на них!
        image: 'films_photo/Taylor Swift_ The Eras Tour (2023).jpg' 
    },
    { 
        id: 2, 
        name: 'All Too Well', 
        time: 15, 
        IMDb_rating: 8.4, 
        price: 150,
        image: 'films_photo/All Too Well (2021).jpg' 
    },
    { 
        id: 3, 
        name: 'Miss Americana', 
        time: 85, 
        IMDb_rating: 7.4, 
        price: 200,
        image: 'films_photo/Miss Americana (2020).jpg' 
    },
    { 
        id: 4, 
        name: 'Reputation Stadium Tour', 
        time: 125, 
        IMDb_rating: 8.4, 
        price: 250,
        image: 'films_photo/Taylor Swift_ Reputation Stadium Tour (2018).jpg' 
    }
];

const FilmsGallery = () => (
    <section className="gallery">
        <div className="grid">
            {sampleFilms.map((f) => (
                <FilmCard key={f.id} film={f} />
            ))}
        </div>
    </section>
);

export default FilmsGallery;
